select public.finish_competition('da95c9e1-a9d1-5b87-8116-64b101397a00', 'tournament_structure') where exists (select 1 from public.competitions where id = 'da95c9e1-a9d1-5b87-8116-64b101397a00' and status <> 'finished');
reset role;
on conflict do nothing;
update public.matches m set finalized_at = m.scheduled_at + make_interval(mins => m.duration_minutes) from public.competitions c where c.id = m.competition_id and c.event_id = '50a32e72-97da-5e2f-9657-fb9c0a8b0efc' and m.queue_state = 'final';
update public.audit_log set at = (date '2025-03-16' + time '21:00') at time zone 'America/Edmonton' where event_id = '50a32e72-97da-5e2f-9657-fb9c0a8b0efc';
commit;
